package io.github.julianperge.modular_planters.multiblock;

import net.minecraft.world.level.block.entity.BlockEntity;

import java.util.ArrayList;
import java.util.List;

final class LiveBlocks {
    private LiveBlocks() {
    }

    // A pool is only rebuilt when the core's scan changes, so a block broken or unloaded since then is still listed.
    // This returns only the blocks that are not removed and asks the core to rescan when it finds a removed one.
    static <T extends BlockEntity> List<T> of(List<T> blocks, Runnable onStale) {
        List<T> live = new ArrayList<>(blocks.size());
        boolean stale = false;
        for (T block : blocks) {
            if (block.isRemoved()) {
                stale = true;
            } else {
                live.add(block);
            }
        }
        if (stale) {
            onStale.run();
        }
        return live;
    }
}
package io.github.julianperge.modular_planters.multiblock;

import io.github.julianperge.modular_planters.blockentity.PowerBlockEntity;
import net.neoforged.neoforge.transfer.energy.EnergyHandler;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;

import java.util.List;

public final class PowerPool {
    private final List<PowerBlockEntity> blocks;
    private final Runnable onStale;
    private final EnergyHandler insertView = new InsertView();

    public PowerPool(List<PowerBlockEntity> inOrder, Runnable onStale) {
        this.blocks = List.copyOf(inOrder);
        this.onStale = onStale;
    }

    private List<PowerBlockEntity> live() {
        return LiveBlocks.of(blocks, onStale);
    }

    public long stored() {
        long total = 0;
        for (PowerBlockEntity block : live()) {
            total += block.stored();
        }
        return total;
    }

    public long capacity() {
        long total = 0;
        for (PowerBlockEntity block : live()) {
            total += block.capacity();
        }
        return total;
    }

    public boolean tryTake(long amount) {
        if (amount < 0 || stored() < amount) {
            return false;
        }
        long remaining = amount;
        for (PowerBlockEntity block : live()) {
            int taken = (int) Math.min(remaining, block.stored());
            if (taken > 0) {
                block.setStored(block.stored() - taken);
                remaining -= taken;
            }
        }
        return true;
    }

    public long refillFrom(MeLink me, long wanted) {
        if (!me.online()) {
            return 0;
        }
        List<PowerBlockEntity> live = live();
        long room = 0;
        for (PowerBlockEntity block : live) {
            room += Math.max(0, block.capacity() - block.stored());
        }
        long asked = Math.min(wanted, room);
        if (asked <= 0) {
            return 0;
        }
        long moved = me.extractEnergy(asked, false);
        long remaining = moved;
        for (PowerBlockEntity block : live) {
            int added = (int) Math.min(remaining, Math.max(0, block.capacity() - block.stored()));
            if (added > 0) {
                block.setStored(block.stored() + added);
                remaining -= added;
            }
        }
        return moved;
    }

    public EnergyHandler insertView() {
        return insertView;
    }

    private final class InsertView implements EnergyHandler {
        @Override
        public long getAmountAsLong() {
            return stored();
        }

        @Override
        public long getCapacityAsLong() {
            return capacity();
        }

        @Override
        public int insert(int amount, TransactionContext transaction) {
            int inserted = 0;
            for (PowerBlockEntity block : live()) {
                if (inserted == amount) {
                    break;
                }
                inserted += block.externalHandler().insert(amount - inserted, transaction);
            }
            return inserted;
        }

        @Override
        public int extract(int amount, TransactionContext transaction) {
            return 0;
        }
    }
}
package io.github.julianperge.modular_planters.ate;

import com.misterd.agritechevolved.AgritechEvolved;
import com.misterd.agritechevolved.Config;
import com.misterd.agritechevolved.datamap.ATEDataMaps;
import com.misterd.agritechevolved.datamap.FertilizerData;
import com.misterd.agritechevolved.datamap.SoilModifierData;
import com.misterd.agritechevolved.recipe.ATERecipeTypes;
import com.misterd.agritechevolved.recipe.CropRecipe;
import com.misterd.agritechevolved.recipe.DropEntry;
import com.misterd.agritechevolved.recipe.TreeRecipe;
import com.misterd.agritechevolved.util.ATETags;
import io.github.julianperge.modular_planters.logic.AteNumbers;
import io.github.julianperge.modular_planters.logic.ModuleKind;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.function.Predicate;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.RandomSource;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.Ingredient;
import net.minecraft.world.item.crafting.RecipeHolder;
import net.minecraft.world.item.crafting.SingleRecipeInput;
import net.neoforged.neoforge.transfer.item.ItemResource;
import org.jspecify.annotations.Nullable;

public final class AteBridge {
    private static Set<Item> cachedSoils = Set.of();
    private static int cachedSoilRevision = -1;

    private AteBridge() {
    }

    public record PlantRecipe(List<DropEntry> drops, Predicate<ItemStack> soilMatches) {
    }

    public static AteNumbers numbers() {
        return new AteNumbers(
                Config.getAdvancedPlanterBaseProcessingTime(), Config.getPlanterBasePowerConsumption(),
                Config.getSpeedModuleMk1Multiplier(), Config.getSpeedModuleMk2Multiplier(),
                Config.getSpeedModuleMk3Multiplier(),
                Config.getSpeedModuleMk1PowerMultiplier(), Config.getSpeedModuleMk2PowerMultiplier(),
                Config.getSpeedModuleMk3PowerMultiplier(),
                Config.getYieldModuleMk1Multiplier(), Config.getYieldModuleMk2Multiplier(),
                Config.getYieldModuleMk3Multiplier(),
                Config.getYieldModuleMk1SpeedPenalty(), Config.getYieldModuleMk2SpeedPenalty(),
                Config.getYieldModuleMk3SpeedPenalty(),
                Config.getClocheSpeedMultiplier(), Config.getClocheYieldMultiplier());
    }

    public static boolean isModule(ItemStack stack) {
        return stack.is(ATETags.Items.ATE_MODULES);
    }

    public static ModuleKind moduleKind(ItemStack stack) {
        return ModuleKind.fromItemId(BuiltInRegistries.ITEM.getKey(stack.getItem()).toString());
    }

    // This follows AdvancedPlanterBlockEntity.getSoilGrowthModifier, so a soil grows seeds at the same speed here as in a single planter.
    public static float soilModifier(ItemStack soil) {
        if (soil.isEmpty()) {
            return 1.0f;
        }
        SoilModifierData data = soil.typeHolder().getData(ATEDataMaps.SOIL_MODIFIERS);
        return data != null ? data.growthModifier() : 1.0f;
    }

    public static @Nullable FertilizerData fertilizer(ItemResource resource) {
        return resource.typeHolder().getData(ATEDataMaps.FERTILIZERS);
    }

    // This follows AdvancedPlanterBlockEntity.refreshRecipeCacheIfNeeded, which tries crop recipes before tree recipes.
    public static Optional<PlantRecipe> recipe(ServerLevel level, ItemStack seed) {
        if (seed.isEmpty()) {
            return Optional.empty();
        }
        SingleRecipeInput input = new SingleRecipeInput(seed);
        Optional<RecipeHolder<CropRecipe>> crop =
                level.recipeAccess().getRecipeFor(ATERecipeTypes.CROP_TYPE.get(), input, level);
        if (crop.isPresent()) {
            CropRecipe recipe = crop.get().value();
            return Optional.of(new PlantRecipe(recipe.getDrops(), recipe::matchesSoil));
        }
        Optional<RecipeHolder<TreeRecipe>> tree =
                level.recipeAccess().getRecipeFor(ATERecipeTypes.TREE_TYPE.get(), input, level);
        return tree.map(holder -> new PlantRecipe(holder.value().getDrops(), holder.value()::matchesSoil));
    }

    // This follows AdvancedPlanterBlockEntity.getValidSoils, whose soil set refreshes only when AgritechEvolved.RECIPE_REVISION changes.
    // Ingredient.items() is deprecated, but NeoForge's replacement getValues() throws on custom ingredients, and ATE lists soils with items() too.
    @SuppressWarnings("deprecation")
    public static boolean isSoilForAnyRecipe(ServerLevel level, ItemStack soil) {
        if (soil.isEmpty()) {
            return false;
        }
        if (cachedSoilRevision != AgritechEvolved.RECIPE_REVISION) {
            Set<Item> soils = new HashSet<>();
            for (RecipeHolder<?> holder : level.recipeAccess().getRecipes()) {
                List<Ingredient> ingredients;
                if (holder.value() instanceof CropRecipe crop) {
                    ingredients = crop.getSoils();
                } else if (holder.value() instanceof TreeRecipe tree) {
                    ingredients = tree.getSoils();
                } else {
                    continue;
                }
                for (Ingredient ingredient : ingredients) {
                    ingredient.items().map(Holder::value).forEach(soils::add);
                }
            }
            cachedSoils = soils;
            cachedSoilRevision = AgritechEvolved.RECIPE_REVISION;
        }
        return cachedSoils.contains(soil.getItem());
    }

    // This follows AdvancedPlanterBlockEntity.getHarvestDrops, except that an entry whose rolled count is 0 is skipped.
    public static List<ItemStack> rollDrops(List<DropEntry> drops, RandomSource random) {
        List<ItemStack> rolled = new ArrayList<>();
        for (DropEntry entry : drops) {
            if (random.nextFloat() <= entry.chance()) {
                int count = entry.max() > entry.min()
                        ? entry.min() + random.nextInt(entry.max() - entry.min() + 1)
                        : entry.min();
                if (count > 0) {
                    rolled.add(new ItemStack(entry.item(), count));
                }
            }
        }
        return rolled;
    }
}
package io.github.julianperge.modular_planters.menu;

import io.github.julianperge.modular_planters.ate.AteBridge;
import io.github.julianperge.modular_planters.blockentity.CoreBlockEntity;
import io.github.julianperge.modular_planters.blockentity.PlanterBlockEntity;
import io.github.julianperge.modular_planters.blockentity.PlanterStatus;
import io.github.julianperge.modular_planters.network.SeedBinCombosPayload;
import io.github.julianperge.modular_planters.registry.MPBlocks;
import io.github.julianperge.modular_planters.registry.MPMenus;
import java.util.List;
import java.util.function.IntSupplier;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.ContainerInput;
import net.minecraft.world.inventory.DataSlot;
import net.minecraft.world.inventory.Slot;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.neoforged.neoforge.network.PacketDistributor;
import net.neoforged.neoforge.transfer.item.ResourceHandlerSlot;

public final class PlanterMenu extends AbstractContainerMenu {
    public static final int SEED = 0, SOIL = 1, MODULE_1 = 2, MODULE_2 = 3;
    private static final int PLAYER_START = 4;
    private static final int HOTBAR_SIZE = 9;
    private static final int OFFHAND = 40;

    private final PlanterBlockEntity planter;
    private final BlockPos anchor;
    private final boolean fromCore;
    private final Player player;
    private final SeedBinSlot seedSlot;
    private final DataSlot status;
    private final DataSlot growing;
    private final DataSlot upgraded;
    private List<ItemStack> sentCombos = List.of();

    public PlanterMenu(int id, Inventory inventory, PlanterBlockEntity planter, BlockPos anchor, boolean fromCore) {
        super(MPMenus.PLANTER.get(), id);
        this.planter = planter;
        this.anchor = anchor;
        this.fromCore = fromCore;
        this.player = inventory.player;
        Level level = inventory.player.level();
        seedSlot = new SeedBinSlot(planter, level, 26, 18);
        addSlot(seedSlot);
        addSlot(new SoilSlot(planter, level, 62, 18));
        addSlot(new ModuleSlot(planter, PlanterBlockEntity.MODULE_1, 98, 18));
        addSlot(new ModuleSlot(planter, PlanterBlockEntity.MODULE_2, 116, 18));
        addStandardInventorySlots(inventory, 8, 85);
        if (seedSlot.authoritative()) {
            status = addDataSlot(readOnly(() -> planter.status().ordinal()));
            growing = addDataSlot(readOnly(planter::growing));
            upgraded = addDataSlot(readOnly(planter::upgraded));
        } else {
            status = addDataSlot(DataSlot.standalone());
            growing = addDataSlot(DataSlot.standalone());
            upgraded = addDataSlot(DataSlot.standalone());
        }
    }

    // The planter here only holds the items the server syncs into the slots, because the real one lives on the server.
    public static PlanterMenu onClient(int id, Inventory inventory, BlockPos pos, boolean fromCore) {
        PlanterBlockEntity detached = new PlanterBlockEntity(pos, MPBlocks.PLANTER.get().defaultBlockState());
        return new PlanterMenu(id, inventory, detached, pos, fromCore);
    }

    public static void open(ServerPlayer player, PlanterBlockEntity planter, BlockPos anchor, boolean fromCore) {
        player.openMenu(new SimpleMenuProvider((id, inventory, opener) -> new PlanterMenu(id, inventory, planter, anchor, fromCore),
                Component.translatable("container.modular_planters.planter")), buffer -> {
            buffer.writeBlockPos(planter.getBlockPos());
            buffer.writeBoolean(fromCore);
        });
    }

    private static DataSlot readOnly(IntSupplier value) {
        return new DataSlot() {
            @Override
            public int get() {
                return value.getAsInt();
            }

            @Override
            public void set(int ignored) {
            }
        };
    }

    public BlockPos anchor() {
        return anchor;
    }

    public boolean fromCore() {
        return fromCore;
    }

    public PlanterStatus status() {
        PlanterStatus[] all = PlanterStatus.values();
        return all[Math.clamp(status.get(), 0, all.length - 1)];
    }

    public int growing() {
        return growing.get();
    }

    public int upgraded() {
        return upgraded.get();
    }

    public List<ItemStack> combos() {
        return seedSlot.combos();
    }

    public int seedCount() {
        return seedSlot.seedCount();
    }

    public void showCombos(List<ItemStack> combos) {
        seedSlot.show(combos);
    }

    @Override
    public void clicked(int slotIndex, int button, ContainerInput input, Player clicker) {
        if (slotIndex == SEED && input == ContainerInput.PICKUP && (button == 0 || button == 1)) {
            resetQuickCraft();
            clickSeedSlot(button == 0);
        } else if (slotIndex == SEED && input == ContainerInput.SWAP && (button >= 0 && button < HOTBAR_SIZE || button == OFFHAND)) {
            swapSeedSlot(clicker, button);
        } else {
            super.clicked(slotIndex, button, input, clicker);
        }
    }

    private void clickSeedSlot(boolean primary) {
        if (!seedSlot.authoritative()) {
            return;
        }
        ItemStack carried = getCarried();
        if (carried.isEmpty()) {
            int count = seedSlot.seedCount();
            setCarried(seedSlot.takeRun(primary ? count : (count + 1) / 2));
        } else {
            seedSlot.insert(carried, primary ? carried.getCount() : 1);
            if (carried.isEmpty()) {
                setCarried(ItemStack.EMPTY);
            }
        }
    }

    private void swapSeedSlot(Player clicker, int hotbarSlot) {
        if (!seedSlot.authoritative()) {
            return;
        }
        ItemStack held = clicker.getInventory().getItem(hotbarSlot);
        if (held.isEmpty()) {
            clicker.getInventory().setItem(hotbarSlot, seedSlot.takeRun(Integer.MAX_VALUE));
        } else {
            seedSlot.insert(held, held.getCount());
            if (held.isEmpty()) {
                clicker.getInventory().setItem(hotbarSlot, ItemStack.EMPTY);
            }
        }
    }

    @Override
    public boolean canDragTo(Slot slot) {
