        return true;
    }

    @Override
    public boolean stillValid(Player clicker) {
        if (planter.isRemoved() || !clicker.isWithinBlockInteractionRange(anchor, 4.0)) {
            return false;
        }
        return !fromCore || stillInCoreStructure();
    }

    private boolean stillInCoreStructure() {
        Level level = planter.getLevel();
        if (level == null || !(level.getBlockEntity(anchor) instanceof CoreBlockEntity core) || core.multiblock() == null) {
            return false;
        }
        return core.multiblock().planters().contains(planter.getBlockPos());
    }

    private static final class SoilSlot extends ResourceHandlerSlot {
        private final PlanterBlockEntity planter;
        private final Level level;

        SoilSlot(PlanterBlockEntity planter, Level level, int x, int y) {
            super(planter.soilAndModules(), planter.soilAndModules()::set, PlanterBlockEntity.SOIL, x, y);
            this.planter = planter;
            this.level = level;
        }

        @Override
        public boolean mayPlace(ItemStack stack) {
            if (!super.mayPlace(stack)) {
                return false;
            }
            if (!(level instanceof ServerLevel server)) {
                return true;
            }
            if (!AteBridge.isSoilForAnyRecipe(server, stack)) {
                return false;
            }
            if (planter.seeds().size() == 0) {
                return true;
            }
            return AteBridge.recipe(server, planter.seeds().seed(0))
                    .map(recipe -> recipe.soilMatches().test(stack))
                    .orElse(true);
        }
    }

    private static final class ModuleSlot extends ResourceHandlerSlot {
        ModuleSlot(PlanterBlockEntity planter, int handlerSlot, int x, int y) {
            super(planter.soilAndModules(), planter.soilAndModules()::set, handlerSlot, x, y);
        }

        @Override
        public boolean mayPlace(ItemStack stack) {
            return super.mayPlace(stack) && AteBridge.isModule(stack);
        }
    }
